document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("stairs-form"),n=document.getElementById("stairs-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("stairs-total-rise").value),s=parseFloat(document.getElementById("stairs-total-run").value),i=parseFloat(document.getElementById("stairs-riser").value),a=parseFloat(document.getElementById("stairs-tread").value);if(t<=0||i<=0||a<=0)return n.textContent="Please enter all dimensions with positive values.",void 0;const o=Math.round(t/i),r=t/o,p=(o-1)*a,l=r>=4&&r<=7.75,d=a>=10,u=r+a,c=2*r+a,m=!s||p<=s,h=s?s-p:0;let g=[],$=[];l||g.push(`⚠️ Riser height ${r.toFixed(2)}" is outside code range (4-7.75")`),d||g.push(`⚠️ Tread depth ${a}" is below minimum (10")`),(u<17||u>18)&&$.push(`📐 Rise + Run = ${u.toFixed(1)}" (ideal: 17-18")`),(c<24||c>25)&&$.push(`📐 2×Rise + Run = ${c.toFixed(1)}" (ideal: 24-25")`),m||g.push(`🚧 Stairs need ${p.toFixed(1)}" but only ${s}" available`);const v=Math.atan(r/a)*(180/Math.PI);n.innerHTML=`\n        <div class="result-section">\n          <h4>Stair Calculations:</h4>\n          <p><strong>${o} steps</strong> (risers)</p>\n          <p><strong>Riser height: ${r.toFixed(3)}"</strong> each</p>\n          <p><strong>Tread depth: ${a}"</strong> each</p>\n          <p><strong>Total run needed: ${p.toFixed(1)}"</strong></p>\n          ${s?`<p>Available space: ${s}" (${h>=0?"fits!":"too tight!"})</p>`:""}\n        </div>\n        \n        <div class="result-proportions">\n          <h4>Design Proportions:</h4>\n          <p>Rise + Run: ${u.toFixed(1)}" ${u>=17&&u<=18?"✅":"⚠️"}</p>\n          <p>2×Rise + Run: ${c.toFixed(1)}" ${c>=24&&c<=25?"✅":"⚠️"}</p>\n          <p>Stair angle: ${v.toFixed(1)}° ${v>=30&&v<=40?"✅":"⚠️"}</p>\n        </div>\n        \n        <div class="result-compliance">\n          <h4>Building Code Compliance:</h4>\n          <p>Riser height: ${l?"✅ Compliant":"❌ Non-compliant"}</p>\n          <p>Tread depth: ${d?"✅ Compliant":"❌ Non-compliant"}</p>\n          <p>Uniformity: ✅ All steps identical</p>\n        </div>\n        \n        ${g.length>0?`\n        <div class="result-warnings">\n          <h4>Warnings:</h4>\n          ${g.map(e=>`<p>${e}</p>`).join("")}\n        </div>\n        `:""}\n        \n        ${$.length>0?`\n        <div class="result-recommendations">\n          <h4>Optimization Suggestions:</h4>\n          ${$.map(e=>`<p>${e}</p>`).join("")}\n        </div>\n        `:""}\n        \n        <div class="result-materials">\n          <h4>Material Estimates:</h4>\n          <p>Stringers: ${o<=14?"2×12":"2×14"} lumber × 2-3 pieces</p>\n          <p>Treads: ${o-1} pieces @ ${a}" deep</p>\n          <p>Risers: ${o} pieces @ ${r.toFixed(2)}" high</p>\n        </div>\n        \n        <div class="result-tips">\n          <p><em>💡 Always verify local building codes before construction</em></p>\n          <p><em>📏 Double-check measurements and use a professional for complex stairs</em></p>\n          <p><em>🔨 Consider hiring a contractor for structural stairs</em></p>\n        </div>\n      `})});